		{ text = "Superpegajoso" },
	},
	bonds = {
		{ id = "krazek", name = "Krazek", note = "su primo, al que debe una entrega" },
	},
})

Translate("esMX", "trenton-lighthammer", {
	title = "Trenton Lighthammer",
	subtitle = "La Orden del Mitril",
