Translate("esMX", "krinkle-goodsteel", {
	title = "Krinkle Goodsteel",
	found = "Gadgetzan, junto a la forja",
	hint = [=[Busque al herrero goblin de Gadgetzan que vende su oficio al mejor postor.]=],
	allegiance = "Gadgetzan",
	sections = {
