		{ text = "Molde rima con..." },
		{ text = "Forjado en el Penacho en Llamas" },
	},
})

Translate("esMX", "shreev", {
	title = "Shreev",
	found = "El Gizmorium de Gadgetzan",
	hint = [=[Busque al goblin del Gizmorium que fabrica explosivos para corredores.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Resumen",
			text = [=[Shreev lleva el Gizmorium de {link:gadgetzan}Gadgetzan{/link}. Fabrica explosivos, y entre sus clientes están los corredores goblins de {link:the-shimmering-flats}El Desierto de Sal{/link}. {link:razzeric}Razzeric{/link} le encargó un propulsor de seforio. Shreev ya lo había hecho más potente de lo que era seguro, y le puso un seguro. Razzeric lo devolvió. Shreev quitó el seguro, y advirtió que un solo error dejaría al corredor convertido en una mancha quemada en la pista.]=],
