	hint = [=[Busque al erudito goblin que acampa entre las ruinas trols del desierto.]=],
	allegiance = "Trinquete",
	aliases = { "Marvon" },
	sections = {
		{
			title = "Resumen",
			text = [=[Marvon Rivetseeker es un goblin de {link:ratchet}Trinquete{/link}, científico y, según él mismo, cazador de tesoros de corazón. Ha estudiado muchos lugares antiguos del mundo y ahora acampa en el desierto para estudiar sus ruinas trols. Colecciona los ornamentos de Gahz'ridian, una piedra que los trols tallaban con la forma de su dios hidra, y construyó un casco que los encuentra. Una vez entró en el {link:temple-of-atal-hakkar}Templo Sumergido{/link} y escapó por poco. De su círculo de estatuas de serpiente, solo recuerda fragmentos.]=],
		},
	},
	chapters = {
		{
			title = "El círculo de piedra",
			hint = "Ayude al erudito goblin a recordar el Templo Sumergido.",
			text = [=[Marvon había encontrado una piedra redonda marcada con el mismo signo de serpiente que había visto en el templo, y la había enviado a su taller de {link:ratchet}Trinquete{/link}. Cuando se la llevaron, recuperó la memoria: seis balcones, seis estatuas de serpiente y un altar de {link:hakkar}Hakkar{/link} abajo.]=],
		},
	},
	mentions = {
		{ text = "Gahz'ridian" },
		{ text = "El {link:temple-of-atal-hakkar}Templo Sumergido{/link}" },
